// AUDIT 2026-09-11 | SABIT KADEME KALDIRILDI.
//
// ONCE: `const KADEME = 'meta5';` - BES PARCADAN BIRI, ELLE yazilmis.
// Haftalik zamanlansaydi her hafta AYNI 4.933 repoyu (kulliyatin 1/5'i)
// tazeler, diger %80'i SONSUZA KADAR bayat birakirdi. Hata da vermezdi.
//
// SIMDI: bes parcanin hepsi okunur, her repo KENDI kademesini tasir
// (cikti dosyasi kademe basina; `Satir Ekle` artik dugum yerine SATIRDAN okur).
const fs = require('fs');
const GIRDI = '/data/ds21final/input/';
const cikti = [];
for (let i = 1; i <= 5; i++) {
  const kademe = 'meta' + i;
  const yol = GIRDI + 'repos_' + kademe + '.csv';
  if (!fs.existsSync(yol)) { continue; }
  const satirlar = fs.readFileSync(yol, 'utf8').split('\n');
  for (let k = 1; k < satirlar.length; k++) {
    const s = satirlar[k].trim();
    if (!s) { continue; }
    const ad = s.split(',')[0];
    if (!ad || ad.indexOf('/') < 0) { continue; }
    cikti.push({ json: { full_name: ad, kademe: kademe } });
  }
}
console.log('kulliyat=' + cikti.length + ' (5 kademe birlestirildi)');
return cikti;

// AUDIT 2026-09-11 | VARLIK -> YAS TABANLI ONBELLEK.
//
// ONCE: meta_<kademe>.jsonl'de adi gecen repo ATLANIYORDU. Dosyalar 07.09'dan
// DOLU oldugu icin zamanlanmis bir tur HER SEYI atlar ve BOS gecerdi - "basarili"
// raporuyla. Devam-edebilirlik icin dogruydu, TAZELEME icin olumcul.
//
// SIMDI: repo basina SON kayit bulunur; `cekilme` TAZELEME_GUN'den yeniyse atlanir.
// ETag da tasinir - degismemisse GitHub 304 doner ve kota sayacina GIRMEZ.
// KALICI hatalar (404/410) meta_misses.jsonl'de, onlar hep atlanir.
const fs = require('fs');
const DIZIN = '/data/ds21final/meta/';
const KAYIP = '/data/ds21final/logs/meta_misses.jsonl';
const TAZELEME_GUN = 7;

function satirlar(yol) {
  try { return fs.readFileSync(yol, 'utf8').split('\n').filter(function (l) { return l.trim(); }); }
  catch (e) { return []; }
}

// repo -> {cekilme, etag}, EN SON kayit kazanir (refresh_csv.py ile ayni kural)
const son = {};
for (let i = 1; i <= 5; i++) {
  satirlar(DIZIN + 'meta_meta' + i + '.jsonl').forEach(function (l) {
    try {
      const r = JSON.parse(l);
      const ad = (r.repo && r.repo.full_name) || r.full_name;
      if (!ad) { return; }
      const o = son[ad];
      if (!o || String(r.cekilme || '') >= String(o.cekilme || '')) {
        son[ad] = { cekilme: r.cekilme, etag: r.etag || '' };
      }
    } catch (e) {}
  });
}
const kalici = new Set();
satirlar(KAYIP).forEach(function (l) {
  try { const r = JSON.parse(l); if (r.full_name) { kalici.add(r.full_name); } } catch (e) {}
});

function yasGun(iso) {
  if (!iso) { return 1e9; }
  const t = new Date(iso).getTime();
  return isNaN(t) ? 1e9 : (Date.now() - t) / 86400000;
}

const hepsi = $input.all();
const kalan = [];
let taze = 0, gone = 0;
hepsi.forEach(function (it) {
  const ad = it.json.full_name;
  if (kalici.has(ad)) { gone++; return; }
  const o = son[ad];
  if (o && yasGun(o.cekilme) <= TAZELEME_GUN) { taze++; return; }
  it.json.etag = (o && o.etag) || '';
  kalan.push(it);
});

console.log('toplam=' + hepsi.length + ' taze=' + taze + ' kalici_hata=' + gone +
            ' cekilecek=' + kalan.length + ' (esik ' + TAZELEME_GUN + ' gun)');
try {
  fs.writeFileSync('/data/ds21final/logs/_meta_son_baslangic.json', JSON.stringify({
    an: new Date().toISOString(), toplam: hepsi.length,
    taze: taze, kalici_hata: gone, cekilecek: kalan.length,
    tazeleme_gun: TAZELEME_GUN
  }, null, 2));
} catch (e) {}
return kalan;

// Repo basina AYRI DOSYA degil, kademe basina JSONL.
// 24.664 kucuk dosya bu bind mount'ta (gRPC-FUSE) daha once hizi
// 5,3 repo/sn'den 0,3'e dusurmustu - README akisinda olculdu.
//
// ANAHTAR: govde.full_name - API'nin KENDI kimlik beyani.
// pairedItem KULLANILMIYOR. 2026-09-07'de olculdu: bu dugumde pairedItem
// yanlis hizalaniyor ve baska bir reponun yanitina yanlis ad yapistiriyordu.
// Kanit: "yeniden adlandirilmis" isaretlenen 266 satirin 243'unde HER IKI ad
// da CSV'de vardi (gercek bir renamede imkansiz), ve A->B, B->C seklinde
// kayma zinciri gorunuyordu. 3 kayitlik sonda temiz cikmisti; batching
// (4 istek/3 sn) ve hata dali devredeyken bozuluyor.
//
// SONUC: istenen ad ile yanit adi arasindaki fark burada COZULMEZ.
// Yeniden adlandirilan repolar yanit adiyla yazilir, CSV ile eslesmezler ve
// refresh_csv.py onlari "tazelenmemis" sayar. Uzlastirma Python tarafinda,
// tam bilgiyle yapilir - n8n yalnizca KESIN bildigini yazar.
const fs = require('fs');
// AUDIT 2026-09-11 | kademe artik DUGUMDEN degil SATIRDAN geliyor:
// tur artik tek kademe degil TUM kulliyati isliyor, yani her repo
// kendi cikti dosyasina yazilmali. $('...').first() hepsini ayni
// dosyaya yazardi ve refresh_csv.py'nin glob'u onu yine okurdu ama
// kademe dosyalari anlamsizlasirdi.
const kademe = $input.first().json.kademe || 'tazeleme';
const CIKTI = '/data/ds21final/meta/meta_' + kademe + '.jsonl';

const satirlar = [];
var atlanan = 0;

for (const it of $input.all()) {
  const j = it.json || {};
  const govde = j.body || {};
  const basliklar = j.headers || {};

  // Kimliksiz satir YAZILMAZ: birlestirme full_name ile yapiliyor.
  if (!govde.full_name) { atlanan++; continue; }

  satirlar.push(JSON.stringify({
    full_name: govde.full_name,        // API'nin beyani - TEK guvenilir anahtar
    etag: basliklar.etag || null,      // Faz 6: If-None-Match -> 304 kota harcamaz
    status: j.statusCode || null,
    cekilme: new Date().toISOString(),
    repo: govde
  }));
}

if (satirlar.length) {
  fs.appendFileSync(CIKTI, satirlar.join('\n') + '\n', 'utf8');
}
if (atlanan) {
  console.log('UYARI: full_name olmadigi icin ' + atlanan + ' yanit yazilmadi');
}

// Repo govdelerini donguye geri VERMIYORUZ - 24.664 x ~5 KB bellekte birikirdi.
return [{ json: { yazildi: satirlar.length, atlanan: atlanan } }];

// Hata dalindaki item'in sekli 2026-09-06 duman testinde OLCULDU:
// ['full_name', 'safe_name', 'error'] - n8n girdi item'ini koruyup uzerine
// 'error' ekliyor, yani full_name'i geri kazanmak guvenli.
const fs = require('fs');
const kademe = $('Kademe Secimi').first().json.kademe;
const KAYIP_YOL = '/data/ds21final/logs/meta_misses.jsonl';

const satirlar = $input.all().map(function (it) {
  const j = it.json || {};
  const e = j.error || {};
  const durum = e.httpCode || e.status || e.statusCode || j.statusCode || null;
  return JSON.stringify({
    an: new Date().toISOString(),
    kademe: kademe,
    full_name: j.full_name || null,
    status: durum ? Number(durum) : null,
    mesaj: String(e.message || j.message || '').slice(0, 200)
  });
});

if (satirlar.length) {
  fs.appendFileSync(KAYIP_YOL, satirlar.join('\n') + '\n', 'utf8');
}
console.log('kayip=' + satirlar.length);

return [{ json: { kayip: satirlar.length } }];

// Dongu bittiginde BIR kez calisir. 'Bitti' (Limit 1) bunun icin var:
// splitInBatches'in main[0] cikisi 'done' dalidir, main[1] ise dongu govdesi.
const fs = require('fs');
const kademe = $('Kademe Secimi').first().json.kademe;
const CIKTI = '/data/ds21final/meta/meta_' + kademe + '.jsonl';

function satirSay(yol) {
  try {
    return fs.readFileSync(yol, 'utf8').split('\n').filter(function (l) { return l.trim(); }).length;
  } catch (e) { return 0; }
}

const rapor = {
  an: new Date().toISOString(),
  kademe: kademe,
  dosya: CIKTI,
  yazilan_satir: satirSay(CIKTI),
  kayip_satir: satirSay('/data/ds21final/logs/meta_misses.jsonl')
};

try {
  fs.writeFileSync('/data/ds21final/logs/_meta_rapor.json', JSON.stringify(rapor, null, 2));
} catch (e) {}

console.log(JSON.stringify(rapor));
return [{ json: rapor }];
